package main

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"testing"

	"github.com/DonaldMurillo/gofastr/cmd/gofastr/internal/clitest"
)

// The generated apps more than one test in this package boots, each built
// once per test binary (clitest.SharedTree). The example apps are
// exampleTree's.

// testAppSpecBin is the built app's name inside testAppSpecTree.
var testAppSpecBin = clitest.TestExecutablePath("generated-app-spec-app")

// testAppSpecTree is clitest.TestAppSpecYAML's app: generated by the CLI
// the way a user runs it, tidied, and built. The HTTP, MCP and dev-loop
// end-to-end tests boot it; each boot keeps its database outside the tree,
// and the dev-loop test, which edits a source file, works on a copy.
func testAppSpecTree(t *testing.T) (dir, appBin string) {
	t.Helper()
	repoRoot := clitest.RepoRootDir(t)
	dir = clitest.SharedTree(t, "test-app-spec", func(dir string) error {
		return generateTestAppSpecApp(repoRoot, dir)
	})
	return dir, filepath.Join(dir, testAppSpecBin)
}

func generateTestAppSpecApp(repoRoot, dir string) error {
	goVersion, err := clitest.RepoGoVersion(repoRoot)
	if err != nil {
		return fmt.Errorf("repoGoVersion: %w", err)
	}
	goMod := "module example.com/demo\n\ngo " + goVersion + "\n\nrequire github.com/DonaldMurillo/gofastr v0.0.0\n\nreplace github.com/DonaldMurillo/gofastr => " + repoRoot + "\n"
	if err := os.Mkdir(filepath.Join(dir, "public"), 0o700); err != nil {
		return err
	}
	for _, f := range []struct{ name, content string }{
		{"go.mod", goMod},
		{"gofastr.yml", clitest.TestAppSpecYAML()},
		{"public/hello.txt", "static from generated app"},
	} {
		if err := os.WriteFile(filepath.Join(dir, filepath.FromSlash(f.name)), []byte(f.content), 0o600); err != nil {
			return err
		}
	}
	if err := clitest.CopyGoSum(repoRoot, dir); err != nil {
		return fmt.Errorf("copy go.sum: %w", err)
	}
	cli, err := clitest.GofastrTestBinary()
	if err != nil {
		return fmt.Errorf("build gofastr: %w", err)
	}
	if err := runIn(dir, nil, cli, "generate", "app", "gofastr.yml"); err != nil {
		return err
	}
	if _, err := os.Stat(filepath.Join(dir, "main.go")); err != nil {
		return fmt.Errorf("generated app entrypoint missing: %w", err)
	}
	// The generated app pulls new imports (driver, batteries); `gofastr dev`
	// builds with the plain toolchain, so the user flow requires a tidy first.
	if err := runIn(dir, nil, "go", "mod", "tidy"); err != nil {
		return err
	}
	return runIn(dir, nil, "go", "build", "-o", filepath.Join(dir, testAppSpecBin), ".")
}

// initScaffoldBin is the built app's name beside initScaffoldTree's
// project, outside it, so the project holds exactly what init wrote plus
// the module setup.
var initScaffoldBin = clitest.TestExecutablePath("scaffold-app")

// initScaffoldTree is `gofastr init blog` with the default flags (sqlite,
// the sample posts entity, module local/blog), pointed at the working tree
// and built. The init build check, the flat-layout check and the scaffold
// boot gate read it; the boot keeps its database outside the tree.
func initScaffoldTree(t *testing.T) (project, appBin string) {
	t.Helper()
	repoRoot := clitest.RepoRootDir(t)
	dir := clitest.SharedTree(t, "init-blog", func(dir string) error {
		cli, err := clitest.GofastrTestBinary()
		if err != nil {
			return fmt.Errorf("build gofastr: %w", err)
		}
		if err := runIn(dir, nil, cli, "init", "blog"); err != nil {
			return err
		}
		project := filepath.Join(dir, "blog")
		if err := setUpGeneratedModule(repoRoot, project); err != nil {
			return err
		}
		if err := runIn(project, []string{"GOFLAGS=-mod=mod"}, "go", "build", "-o", filepath.Join(dir, initScaffoldBin), "."); err != nil {
			return fmt.Errorf("generated project did not build: %w", err)
		}
		return nil
	})
	return filepath.Join(dir, "blog"), filepath.Join(dir, initScaffoldBin)
}

// runIn runs name with args in dir, with env added to the test's own, and
// returns its output in the error when it fails.
func runIn(dir string, env []string, name string, args ...string) error {
	cmd := exec.Command(name, args...)
	cmd.Dir = dir
	cmd.Env = append(os.Environ(), env...)
	if out, err := cmd.CombinedOutput(); err != nil {
		return fmt.Errorf("%s %v: %w\n%s", filepath.Base(name), args, err, out)
	}
	return nil
}
